"""Build the nonconfidential two-page investor results addendum from verified metrics."""
from pathlib import Path
import json
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

FONT_DIR=Path('/usr/share/fonts/truetype/dejavu')
pdfmetrics.registerFont(TTFont('ResearchSans',str(FONT_DIR/'DejaVuSans.ttf')))
pdfmetrics.registerFont(TTFont('ResearchSans-Bold',str(FONT_DIR/'DejaVuSans-Bold.ttf')))
pdfmetrics.registerFontFamily('ResearchSans',normal='ResearchSans',bold='ResearchSans-Bold',italic='ResearchSans',boldItalic='ResearchSans-Bold')

ROOT=Path(__file__).resolve().parents[1]
RUN=ROOT/'results/pilot_20261021_v2'
metric=json.loads((RUN/'metrics.json').read_text())
verified=json.loads((ROOT/'verification/report.json').read_text())
assert verified['verdict']=='PASS' and verified['run']=='pilot_20261021_v2'
OUT=ROOT/'docs/business/Cellular_Rejuvenation_Public_Data_Pilot_2026-10-21.pdf'
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleSmall',fontName='ResearchSans-Bold',fontSize=23,leading=28,textColor=colors.HexColor('#15344D'),spaceAfter=10))
styles.add(ParagraphStyle(name='Subhead',fontName='ResearchSans-Bold',fontSize=11.5,leading=15,textColor=colors.HexColor('#15344D'),spaceBefore=11,spaceAfter=6))
styles.add(ParagraphStyle(name='TextSmall',fontName='ResearchSans',fontSize=9.0,leading=12.4,spaceAfter=7))
styles.add(ParagraphStyle(name='TinyNote',fontName='ResearchSans',fontSize=8.0,leading=10.5,spaceAfter=6,textColor=colors.HexColor('#46535F')))
story=[]
def para(t,s='TextSmall'):story.append(Paragraph(t,styles[s]))
def footer(canvas,doc):
 canvas.setStrokeColor(colors.HexColor('#CAD6DF'));canvas.line(48,42,564,42)
 canvas.setFont('ResearchSans',7.0);canvas.setFillColor(colors.HexColor('#46535F'))
 canvas.drawString(48,29,'21 October 2026 | Preliminary computational evidence | No rejuvenation efficacy established')
 canvas.drawRightString(564,29,str(doc.page))

para('Public-data training pilot','TitleSmall')
para('AI-guided cellular rejuvenation research','Subhead')
para('<b>David Xu, PhD; Peter Lee, PhD, MD; and Zhimin Zheng, PhD</b>')
para('A small, reproducible study learns chronological-age associations in cultured adult fibroblasts. It is an inspectable engineering milestone for a proposed research program. It does not show biological age reversal, identify a causal rejuvenation mechanism or validate a therapeutic target.')
para('<b>Free public data:</b> GEO GSE113957, generated by Fleischer et al. (2018). Of 143 samples, 111 healthy adult cell lines qualified; 88 were used for training and 23 for one frozen holdout. All progeria and pediatric samples were excluded. No paid data, raw-sequencing download, GPU or cloud training was used.')
data=[['Model','Holdout MAE, years','95% bootstrap interval']]
for key,label in [('median_baseline','Training-median baseline'),('ridge','Ridge'),('compact_mlp','Compact neural network')]:
 m=metric['models'][key];ci=m['bootstrap_mae_ci95'];data.append([label,f"{m['mae_years']:.2f}",f'{ci[0]:.2f} to {ci[1]:.2f}'])
t=Table(data,colWidths=[220,140,156],hAlign='LEFT')
t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#15344D')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'ResearchSans-Bold'),('FONTNAME',(0,1),(-1,-1),'ResearchSans'),('FONTSIZE',(0,0),(-1,-1),8.5),('BOTTOMPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),9),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#EDF3F7'),colors.white]),('LINEBELOW',(0,-1),(-1,-1),.5,colors.HexColor('#CAD6DF'))]))
story.append(t);story.append(Spacer(1,9))
para('<b>The neural model did not outperform Ridge.</b> Its paired MAE improvement over Ridge was -1.45 years (95% interval -5.05 to 1.98). Both models passed the predeclared comparison with the median baseline. This is not a comparison establishing superiority over published aging clocks. The neural component has 145 weights and biases, plus fitted PCA and preprocessing parameters.','TinyNote')
story.append(Image(str(RUN/'holdout_results.png'),width=510,height=204))
para('<b>Critical limitations:</b> 23 held-out cell lines; one cohort and one split; no external validation. Training median age was 62.5 versus 46 in the holdout. In held-out adults below 60 (n=14), Ridge MAE was 15.84 years and R-squared was -2.41. The intervals above condition on this split and the fitted models. They do not include uncertainty across new cohorts or new training sets.','TinyNote')
story.append(PageBreak())
para('What the evidence supports','TitleSmall')
para('Training and verification','Subhead')
para('The protocol was frozen before fitting. Public cell IDs defined groups, and no group crossed the training/holdout boundary. Each training fold performed its own transcript filtering, log transformation, variance selection and scaling. Ridge alpha was chosen from four values by grouped inner cross-validation. The neural architecture was fixed: 16 principal components and eight tanh hidden units, with training-only target scaling.')
para('Thirty shuffled-training-label Ridge controls produced mean holdout MAE 24.08 years (range 18.71 to 30.71). This is a diagnostic, not a confirmatory permutation p-value: model selection was not repeated for each shuffle. No holdout-based search for a favorable seed or neural architecture was performed.')
para('<b>Independent software/numeric verification passed 103 checks and all seven tests.</b> Checks covered downloaded data hashes, labels, exclusions, split and inner-fold membership, fitted preprocessing, checkpoint predictions, metrics and bootstrap intervals. A deliberately corrupted prediction record was rejected. V1 source drift from an example-path fix was detected; V2 reran the unchanged protocol with identical predictions and frozen source.')
para('The release includes code, exact dependencies, acquisition scripts, source hashes, sample manifests, per-sample predictions, model checkpoints and result files. CPU fitting took 2.19 seconds here, excluding download, setup, development and verification; direct cloud spending was $0. This timing is not a claim of end-to-end research cost or expected therapeutic development cost.')
para('Boundaries investors should understand','Subhead')
para('This is an association study on an existing cohort. Sex, ancestry, passage, culture and platform can confound prediction. Public cell IDs are a donor proxy, not independently confirmed donor identity or unrelatedness. Gene coefficients are model weights, not experimentally validated mechanisms. No cells were treated in this project and no cell-function, safety, lifespan or clinical outcome was measured.')
para('The proposed venture has no established biological efficacy, proprietary validated target, institutional sponsorship, founder role commitments or clinical results. The existing $8 million, 24-month program is illustrative. Public code and data reanalysis alone do not establish commercial demand or defensible therapeutic IP.')
para('Next decision gate','Subhead')
para('Lock an independent adult fibroblast cohort and expression-harmonization protocol before external evaluation. Assess age-band and batch robustness, then separately test whether intervention-associated predictions track independent function while preserving cell identity. Mechanism claims require prospective perturbation, rescue, independent donors, replication, persistence and safety evidence.')
para('Inspect and reproduce','Subhead')
para('<link href="https://github.com/xuda1979/anti-aging" color="#285F96">https://github.com/xuda1979/anti-aging</link><br/>Study: results/pilot_20261021_v2/REPORT.md<br/>Verification: verification/REPORT.md<br/>Contact: David Xu, PhD - exutechnology@gmail.com','TinyNote')
para('Sources: NCBI GEO GSE113957, https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE113957 ; Fleischer et al., Genome Biology 19, 221 (20 December 2018), https://doi.org/10.1186/s13059-018-1599-6 . Original investigators generated the data. Public download does not establish unrestricted commercial rights. This addendum reports a new limited reanalysis, with AI-assisted implementation and independent computational verification.','TinyNote')
doc=SimpleDocTemplate(str(OUT),pagesize=(612,792),rightMargin=48,leftMargin=48,topMargin=42,bottomMargin=53,title='Public-data training pilot - AI-guided cellular rejuvenation',author='David Xu, PhD; Peter Lee, PhD, MD; Zhimin Zheng, PhD')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(OUT)
